<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/profile-commerce-checkout-v900.php';
$pdo=db();if(!$pdo||!profile_agent_schema_ready($pdo)||!agent_commerce_schema_ready_v800($pdo)){http_response_code(503);exit('Profile Commerce is not ready.');}
$username=profile_username_normalize((string)($_GET['username']??''));$slug=profile_commerce_slug_v900((string)($_GET['product']??''));
$profile=profile_by_username($pdo,$username);if(!$profile||empty($profile['is_active'])||empty($profile['is_public'])){http_response_code(404);exit('Profile not found.');}
$product=profile_commerce_public_product_v900($pdo,$profile,$slug);if(!$product){http_response_code(404);exit('Product not found.');}
$productRow=profile_commerce_owner_product_v900($pdo,(int)$profile['user_id'],(int)$product['id']);if(!$productRow){http_response_code(404);exit('Product not found.');}
$displayName=trim((string)$profile['display_name'])?:$username;$connections=profile_commerce_checkout_connections_v900($pdo,$productRow);$error='';
$token=profile_commerce_token_v900((int)$profile['user_id']);$checkoutNonce=profile_commerce_checkout_nonce_v900((int)$profile['user_id'],(int)$product['id']);$termsDigest=profile_commerce_terms_digest_v900($productRow);$sellerPolicy=trim((string)($productRow['cancellation_policy']??''));
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        if(!profile_commerce_token_valid_v900((int)$profile['user_id'],(string)($_POST['commerce_token']??'')))throw new RuntimeException('Checkout session expired. Refresh and try again.');
        $postedNonce=trim((string)($_POST['checkout_nonce']??''));profile_commerce_checkout_intent_v900((int)$profile['user_id'],(int)$product['id'],$postedNonce);
        if($product['binding_type']==='appointment_event_type')redirect(url('/'.rawurlencode($username).'/book'));
        if($product['payment_mode']==='free')throw new RuntimeException('This offer does not require checkout. Ask the Profile Agent for next steps.');
        $connectionId=(int)($_POST['connection_id']??0);if($connectionId<1&&count($connections)===1)$connectionId=(int)$connections[0]['id'];
        $checkout=profile_commerce_create_checkout_idempotent_v900($pdo,$profile,$product,$connectionId,(string)($_POST['payer_email']??''),$postedNonce,(string)($_POST['terms_digest']??''),!empty($_POST['accept_terms']));
        $checkoutUrl=trim((string)($checkout['checkout_url']??''));if($checkoutUrl===''||!filter_var($checkoutUrl,FILTER_VALIDATE_URL))throw new RuntimeException('Secure checkout could not be created.');redirect($checkoutUrl);
    }catch(Throwable $e){$error=$e->getMessage();}
}
$avatar='';if(!empty($profile['avatar_path'])&&str_starts_with((string)$profile['avatar_path'],'/uploads/'))$avatar=url((string)$profile['avatar_path']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f6f5f2"><link rel="canonical" href="<?=e($product['product_url'])?>"><title><?=e($product['title'])?> · <?=e($displayName)?></title><style>
*{box-sizing:border-box}body{margin:0;background:#f6f5f2;color:#171816;font:15px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.pcp-top{height:64px;border-bottom:1px solid #dedfd9;background:rgba(246,245,242,.95);display:flex;align-items:center;justify-content:space-between;padding:0 24px;position:sticky;top:0}.pcp-top a{color:#171816;text-decoration:none}.pcp-shell{max-width:980px;margin:0 auto;padding:48px 24px}.pcp-back{display:inline-flex;margin-bottom:24px;color:#5f625c;text-decoration:none}.pcp-card{background:#fff;border:1px solid #e0e2dc;border-radius:28px;padding:32px;display:grid;grid-template-columns:minmax(0,1.4fr) minmax(280px,.8fr);gap:32px;box-shadow:0 18px 50px rgba(20,22,18,.05)}.pcp-kicker{font-size:12px;text-transform:uppercase;letter-spacing:.12em;color:#747771}.pcp-title{font-size:38px;line-height:1.05;margin:8px 0 14px}.pcp-description{font-size:17px;color:#555851;white-space:pre-line}.pcp-meta{display:flex;gap:8px;flex-wrap:wrap;margin-top:20px}.pcp-pill{padding:6px 10px;border-radius:999px;background:#f0f1ed;font-size:12px}.pcp-buy{border-left:1px solid #ecece7;padding-left:28px}.pcp-price{font-size:25px;font-weight:750;margin:6px 0 18px}.pcp-form{display:grid;gap:12px}.pcp-form label{display:grid;gap:5px;font-size:13px}.pcp-form input,.pcp-form select{width:100%;padding:12px;border:1px solid #d5d7d0;border-radius:11px;background:#fff;font:inherit}.pcp-form .pcp-accept{display:flex;grid-template-columns:auto 1fr;align-items:flex-start;gap:8px}.pcp-form .pcp-accept input{width:auto;margin-top:4px}.pcp-btn{display:inline-flex;justify-content:center;align-items:center;padding:12px 16px;border:0;border-radius:11px;background:#151614;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.pcp-note{font-size:12px;color:#747771}.pcp-terms{padding:12px;border:1px solid #e1e2dd;border-radius:12px;background:#fafaf8;margin-bottom:12px;font-size:12px;color:#5f625c}.pcp-terms strong{display:block;color:#171816;margin-bottom:4px}.pcp-error{padding:11px 12px;background:#fff0ee;color:#84251f;border-radius:10px;margin-bottom:12px}.pcp-owner{display:flex;align-items:center;gap:10px}.pcp-avatar{width:34px;height:34px;border-radius:50%;background:#e8e9e4;overflow:hidden;display:grid;place-items:center;font-weight:700}.pcp-avatar img{width:100%;height:100%;object-fit:cover}@media(max-width:760px){.pcp-card{grid-template-columns:1fr;padding:22px}.pcp-buy{border-left:0;border-top:1px solid #ecece7;padding:22px 0 0}.pcp-title{font-size:32px}.pcp-shell{padding:30px 16px}}
</style></head><body><header class="pcp-top"><a href="<?=e(profile_public_url($username))?>" class="pcp-owner"><span class="pcp-avatar"><?php if($avatar!==''):?><img src="<?=e($avatar)?>" alt=""><?php else:?><?=e(mb_strtoupper(mb_substr($displayName,0,1)))?><?php endif;?></span><strong><?=e($displayName)?></strong></a><a href="<?=e(profile_public_url($username))?>">Profile</a></header><main class="pcp-shell"><a class="pcp-back" href="<?=e(profile_public_url($username))?>">← Back to @<?=e($username)?></a><section class="pcp-card"><div><span class="pcp-kicker"><?=e(ucfirst((string)$product['product_type']))?> · <?=e(ucfirst((string)$product['fulfillment_type']))?></span><h1 class="pcp-title"><?=e($product['title'])?></h1><?php if(trim((string)$product['description'])!==''):?><div class="pcp-description"><?=e($product['description'])?></div><?php endif;?><div class="pcp-meta"><span class="pcp-pill"><?=e($product['price_label'])?></span><?php if($product['featured']):?><span class="pcp-pill">Featured</span><?php endif;?><span class="pcp-pill">Sold by <?=e($displayName)?></span></div></div><aside class="pcp-buy"><span class="pcp-kicker"><?= $product['binding_type']==='appointment_event_type'?'Scheduling':'Secure Commerce' ?></span><div class="pcp-price"><?=e($product['price_label'])?></div><?php if($error!==''):?><div class="pcp-error" role="alert"><?=e($error)?></div><?php endif;?><?php if($product['binding_type']==='appointment_event_type'):?><form method="post" class="pcp-form"><input type="hidden" name="commerce_token" value="<?=e($token)?>"><input type="hidden" name="checkout_nonce" value="<?=e($checkoutNonce)?>"><button class="pcp-btn" type="submit"><?=e($product['cta'])?></button></form><p class="pcp-note">Appointment availability and lifecycle remain authoritative in Scheduling.</p><?php elseif($product['payment_mode']==='free'):?><a class="pcp-btn" href="<?=e(profile_public_url($username))?>#profile-agent">Ask Profile Agent</a><?php elseif(!$connections):?><p class="pcp-note">Checkout is temporarily unavailable because the seller has no active customer-payment provider.</p><?php else:?><div class="pcp-terms"><strong>Seller terms</strong><span><?= $sellerPolicy!==''?e($sellerPolicy):'No additional cancellation or refund policy was provided. Refunds are handled by the seller through the canonical Commerce ledger.' ?></span></div><form method="post" class="pcp-form"><input type="hidden" name="commerce_token" value="<?=e($token)?>"><input type="hidden" name="checkout_nonce" value="<?=e($checkoutNonce)?>"><input type="hidden" name="terms_digest" value="<?=e($termsDigest)?>"><label>Receipt + fulfillment email<input type="email" name="payer_email" autocomplete="email" maxlength="190" placeholder="you@example.com" required></label><?php if(count($connections)>1):?><label>Payment provider<select name="connection_id" required><option value="">Choose provider</option><?php foreach($connections as $connection):?><option value="<?=(int)$connection['id']?>"><?=e(agent_commerce_provider_label_v800((string)$connection['provider']))?></option><?php endforeach;?></select></label><?php else:?><input type="hidden" name="connection_id" value="<?=(int)$connections[0]['id']?>"><?php endif;?><label class="pcp-accept"><input type="checkbox" name="accept_terms" value="1" required><span>I agree to the displayed price and seller terms.</span></label><button class="pcp-btn" type="submit"><?=e($product['cta'])?></button></form><p class="pcp-note">Payment is handled by the seller’s connected Commerce provider. Your email and accepted terms digest are attached to the canonical order.</p><?php endif;?></aside></section></main></body></html>